"""The 12 assignment questions, verbatim, plus documented as-of date assumptions."""
from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Question:
    id: str
    text: str
    as_of: date | None = None  # only Q9/Q10 are date-dependent
    # Q10 says "answer the same question" with no antecedent in the string itself.
    # Eval runners resolve that anaphora for *retrieval* only; the answer is still
    # generated by the model. Verbatim Q10 text is what gets written to outputs.
    retrieval_text: str | None = None


# Q9/Q10 say "the date given in the question set" but no dates were given in the brief.
# Documented assumption: dates bracketing the First/Second Amendments —
# pre-Amendment 1 (2018-01-01) and post-Amendment 2 (2020-06-01).
AS_OF_EARLY = date(2018, 1, 1)
AS_OF_LATE = date(2020, 6, 1)

QUESTIONS = [
    Question(
        "q1", "What is the governing law of the agreement, and the agreed forum for disputes?"
    ),
    Question(
        "q2",
        "What is the final maturity date of the term loan facility as originally executed?",
    ),
    Question("q3", "Who are the parties to the original agreement, and what role does each hold?"),
    Question(
        "q4",
        "Define the term used for permitted borrowings, and list every section of the agreement "
        "that depends on that definition.",
    ),
    Question(
        "q5",
        "May the Borrower grant a lien over its intellectual property? Cite the covenant, the "
        "operative defined term, and every exception that applies.",
    ),
    Question(
        "q6",
        "A subsidiary wants to make a distribution to its parent. Is it permitted? Walk the chain "
        "from covenant to definition to carve outs.",
    ),
    Question(
        "q7",
        "What happens if the principal financial covenant is breached? Trace cure rights, grace "
        "periods and consequences through to the events of default.",
    ),
    Question(
        "q8",
        "Find one place in the agreement where two sections conflict, or where a cross reference "
        "points to a section that does not say what the referring section implies.",
    ),
    Question(
        "q9",
        "As of the date given in the question set, what is the maximum permitted restricted "
        "payment? Cite the operative version of the operative section.",
        as_of=AS_OF_EARLY,
    ),
    Question(
        "q10",
        "As of the later date given in the question set, answer the same question. Explain what "
        "changed, and when.",
        as_of=AS_OF_LATE,
        retrieval_text=(
            "As of 2020-06-01, what is the maximum permitted restricted payment? Cite the "
            "operative version of the operative section. Explain what changed relative to "
            "2018-01-01, and when."
        ),
    ),
    Question(
        "q11",
        "List every section of the original agreement that has been amended, when, and by which "
        "instrument.",
    ),
    Question(
        "q12",
        "Has the definition of the leverage ratio changed over the life of the agreement? If so, "
        "how does that change affect the sections that rely on it?",
    ),
]
